package com.example.Hospital.Management.System.repositories; import com.example.Hospital.Management.System.entities.Appointment; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.time.*; import java.util.*; public interface AppointmentRepository extends JpaRepository<Appointment,Long>{List<Appointment> findByIsActiveTrue(); long countByDoctorIdAndIsActiveTrue(Long id); @Query("select a from Appointment a where a.doctor.id=:doctorId and a.isActive=true and function('date',a.appointmentDate)=:date") List<Appointment> activeForDoctorOnDate(@Param("doctorId") Long doctorId,@Param("date") LocalDate date);}
